把教材的原型落到可运行的调用上，需要补上三件事：用 `sizeof` 算出字节数、接住返回值、检查是否为空。

```c
#include <stdlib.h>

int n = 5;
int *p = (int *)malloc(n * sizeof(int));
if (p == NULL) {
    /* 分配失败：内存不足，此时不能解引用 p */
    return 1;
}
```

写 `n * sizeof(int)` 而不是写死的数字，保证“5 个整数”在任何平台上都按该平台的整数宽度计算字节数。返回值是 `void *`，赋给 `int *` 之前先做类型转换；若分配失败返回 `NULL`，此时任何对 `p` 的解引用都是非法访问。

**教材示例代码（原例未写显式 free）**

例 8.30：建立动态数组，输入 5 个学生的成绩，另外用一个函数检查其中有无低于 60 分的，输出不合格的成绩。

```c
#include <stdio.h>
#include <stdlib.h>                  /* 程序中用了 malloc 函数，应包含 stdlib.h */
int main()
{ void check(int *);                /* 函数声明 */
  int *p1, i;                        /* p1 是 int 型指针 */
  p1 = (int *)malloc(5 * sizeof(int)); /* 开辟动态内存区，将地址转换成 int * 型，然后放在 p1 中 */
  for (i = 0; i < 5; i++)
      scanf("%d", p1 + i);           /* 输入 5 个学生的成绩 */
  check(p1);                         /* 调用 check 函数 */
  return 0;
}
void check(int *p)                   /* 定义 check 函数，形参是 int * 指针 */
{ int i;
  printf("They are fail:");
  for (i = 0; i < 5; i++)
      if (p[i] < 60) printf("%d ", p[i]); /* 输出不合格的成绩 */
  printf("\n");
}
```

运行结果：

```txt
67 98 59 78 57
They are fail:59 57
```

**教材分析文字摘要**

教材的程序分析指出：程序中没有定义数组，而是开辟一段动态自由分配区，作为动态数组使用；调用 `malloc` 时没有给出具体数值，而是用 `5 * sizeof(int)`，因为不同系统存放一个整数的字节数不同，用 `sizeof` 运算符测定本系统中整数的字节数，程序才具有通用性；返回值是 `void *` 型的，赋给 `p1` 前应先转换成 `int *` 型；输入时不是用数组名，而是按地址赋值给动态数组的 5 个元素；调用 `check` 时把 `p1` 的值传给形参 `p`，因此 `p` 也指向动态区的第 1 个数据，可以认为形参数组与实参数组共享同一段动态分配区；最后用 `free` 函数释放动态分配区。

